Actual code:

```cpp
template <typename N>
typename Earcut<N>::Node* Earcut<N>::sortLinked(Node* list) {
    std::size_t i = 0;
    Node* p = nullptr;
    Node* q = nullptr;
    Node* e = nullptr;
    Node* tail = nullptr;
    std::size_t numMerges = 0;
    std::size_t pSize = 0;
    std::size_t qSize = 0;
    std::size_t inSize = 1;

    while (true) {
        p = list;
        list = nullptr;
        tail = nullptr;
        numMerges = 0;

        while (p) {
            numMerges++;
            q = p;
            pSize = 0;
            for (i = 0; i < inSize; i++) {
                pSize++;
                q = q->nextZ;
                if (!q) break;
            }

            qSize = inSize;

            // if there are more or equal number of nodes in q merge them
            while (pSize > 0 || (qSize > 0 && q)) {
                // decide whether next node of merge comes from p or q
                if (pSize == 0) {
                    // p is empty; e must come from q.
                    e = q;
                    q = q->nextZ;
                    qSize--;
                } else if (qSize == 0 || !q) {
                    // q is empty; e must come from p.
                    e = p;
                    p = p->nextZ;
                    pSize--;
                } else if (p->z <= q->z) {
                    // first node of p is lower or same; e must come from p.
                    e = p;
                    p = p->nextZ;
                    pSize--;
                } else {
                    // first node of q is lower; e must come from q.
                    e = q;
                    q = q->nextZ;
                    qSize--;
                }

                // add the next node to the merged list
                if (tail) tail->nextZ = e;
                else list = e;

                e->prevZ = tail;
                tail = e;
            }

            // now p has stepped `inSize` places along, and q has too
            p = q;
        }

        tail->nextZ = nullptr;

        if (numMerges <= 1) return list;

        inSize *= 2;
    }
}
```

zOrder:

```cpp
// z-order of a vertex given coords and size of the data bounding box
template <typename N>
int32_t Earcut<N>::zOrder(const double x_, const double y_, const double minX, const double minY, const double invSize) {
    // coords are transformed into non-negative 15-bit integer range
    int32_t x = static_cast<int32_t>((x_ - minX) * invSize);
    int32_t y = static_cast<int32_t>((y_ - minY) * invSize);

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    return x | (y << 1);
}
```

Note static_cast<int32_t> of a double truncates toward zero. Values here are in [0, 32767.5], so truncation = floor. In Rust: `as i32` truncates toward zero too.

