fn linked_list(&mut self, points: &[(f64, f64)], clockwise: bool) -> usize {
    let len = points.len();
    let mut sum = 0.0f64;
    let mut i = 0usize;
    let mut j = if len > 0 { len - 1 } else { 0 };
    while i < len {
        let (x1, y1) = points[i];
        let (x2, y2) = points[j];
        sum += (x2 - x1) * (y1 + y2);
        j = i;
        i += 1;
    }

    let mut last = NIL;
    if clockwise == (sum > 0.0) {
        for i in 0..len {
            last = self.insert_node(i as u32, points[i].0, points[i].1, last);
        }
    } else {
        let mut i = len;
        while i > 0 {
            i -= 1;
            last = self.insert_node(i as u32, points[i].0, points[i].1, last);
        }
    }

    if last != NIL && self.equals(last, self.nodes[last].next) {
        self.remove_node(last);
        last = self.nodes[last].next;
    }

    last
}
