fn find_hole_bridge(&mut self, hole: usize, outer_node: usize) -> usize {
    let mut p = outer_node;
    let hx = self.nodes[hole].x;
    let hy = self.nodes[hole].y;
    let mut qx = f64::NEG_INFINITY;
    let mut m = NIL;
    loop {
        let pn = self.nodes[p].next;
        let (px, py, pnx, pny) = (self.nodes[p].x, self.nodes[p].y, self.nodes[pn].x, self.nodes[pn].y);
        if hy <= py && hy >= pny && pny != py {
            let x = px + (hy - py) * (pnx - px) / (pny - py);
            if x <= hx && x > qx {
                qx = x;
                if x == hx {
                    if hy == py { return p; }
                    if hy == pny { return pn; }
