fn sort_linked(&mut self, list: usize) -> usize {
    let mut list = list;
    let mut in_size = 1usize;
    loop {
        let mut p = list;
        list = NIL;
        let mut tail = NIL;
        let mut num_merges = 0usize;
        while p != NIL {
            num_merges += 1;
            let mut q = p;
            let mut p_size = 0usize;
            for _ in 0..in_size {
                p_size += 1;
                q = self.nodes[q].next_z;
                if q == NIL { break; }
            }
            let mut q_size = in_size;
            while p_size > 0 || (q_size > 0 && q != NIL) {
                let e;
                if p_size == 0 {
                    e = q; q = self.nodes[q].next_z; q_size -= 1;
                } else if q_size == 0 || q == NIL {
                    e = p; p = self.nodes[p].next_z; p_size -= 1;
                } else if self.nodes[p].z <= self.nodes[q].z {
                    e = p; p = self.nodes[p].next_z; p_size -= 1;
                } else {
                    e = q; q = self.nodes[q].next_z; q_size -= 1;
                }
                if tail != NIL { self.nodes[tail].next_z = e; } else { list = e; }
                self.nodes[e].prev_z = tail;
                tail = e;
            }
            p = q;
        }
        self.nodes[tail].next_z = NIL;
        if num_merges <= 1 { return list; }
        in_size *= 2;
    }
